package vn.luma;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.mock.web.MockHttpSession;
import vn.luma.business.*;
import vn.luma.web.HanhViController;
import static org.assertj.core.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:postgresql://127.0.0.1:55432/luma_test","app.mail.local-directory=.local/test-mail","app.scheduling.enabled=false"})
@Transactional
class HanhViIntegrationTest {
    @Autowired HanhViService service;
    @Autowired HanhViController controller;
    @Autowired TaiKhoanService users;
    @Autowired BaoCaoService reports;
    @Autowired JdbcClient jdbc;
    long count(String table){return jdbc.sql("SELECT count(*) FROM \""+table+"\"").query(Long.class).single();}
    int seconds(long id){return jdbc.sql("SELECT \"SoGiayHoatDong\" FROM \"PhienTruyCap\" WHERE \"MaPhienTruyCap\"=:id").param("id",id).query(Integer.class).single();}
    @Test void consentIsOffByDefaultAndIdentityChangesNeverMergeOldAnonymousSession(){
        var session=new MockHttpSession();long before=count("PhienTruyCap");var event=new HanhViController.SuKien("XEM_TRANG","CHI_TIET",UUID.randomUUID().toString(),1L);controller.suKien(event,session,null);assertThat(count("PhienTruyCap")).isEqualTo(before);controller.luaChon(true,session);controller.suKien(event,session,null);var anon=(HanhViController.Phien)session.getAttribute(HanhViController.SESSION);controller.suKien(event,session,null);assertThat(jdbc.sql("SELECT count(*) FROM \"TuongTacSanPham\" WHERE \"MaPhienTruyCap\"=:id").param("id",anon.id()).query(Long.class).single()).isEqualTo(1);
        String email="analytics-"+UUID.randomUUID()+"@example.test";users.seedDemo(email,"Khách thống kê","KhachHang","AnalyticsDemo!2026");controller.suKien(event,session,()->email);var logged=(HanhViController.Phien)session.getAttribute(HanhViController.SESSION);assertThat(logged.id()).isNotEqualTo(anon.id());assertThat(jdbc.sql("SELECT \"MaNguoiDung\" IS NULL FROM \"PhienTruyCap\" WHERE \"MaPhienTruyCap\"=:id").param("id",anon.id()).query(Boolean.class).single()).isTrue();assertThat(count("PhienTruyCap")).isEqualTo(before+2);controller.luaChon(false,session);controller.suKien(event,session,()->email);assertThat(count("PhienTruyCap")).isEqualTo(before+2);controller.luaChon(true,session);controller.suKien(event,session,()->"admin@luma.local");assertThat(count("PhienTruyCap")).isEqualTo(before+2);
    }
    @Test void heartbeatCapsElapsedTimeSkipsLongGapsAndRequiresMatchingSessionKey(){String key=UUID.randomUUID().toString();long id=service.tao(key,null);jdbc.sql("UPDATE \"PhienTruyCap\" SET \"LanHoatDongCuoi\"=clock_timestamp()-interval '10 seconds' WHERE \"MaPhienTruyCap\"=:id").param("id",id).update();service.nhip(id,key,true);assertThat(seconds(id)).isBetween(10,15);int first=seconds(id);service.nhip(id,key,true);assertThat(seconds(id)).isBetween(first,first+1);jdbc.sql("UPDATE \"PhienTruyCap\" SET \"LanHoatDongCuoi\"=clock_timestamp()-interval '2 hours' WHERE \"MaPhienTruyCap\"=:id").param("id",id).update();service.nhip(id,key,true);assertThat(seconds(id)).isBetween(first,first+1);jdbc.sql("UPDATE \"PhienTruyCap\" SET \"SoGiayHoatDong\"=28799,\"LanHoatDongCuoi\"=clock_timestamp()-interval '10 seconds' WHERE \"MaPhienTruyCap\"=:id").param("id",id).update();service.nhip(id,key,false);assertThat(seconds(id)).isEqualTo(28799);jdbc.sql("UPDATE \"PhienTruyCap\" SET \"LanHoatDongCuoi\"=clock_timestamp()-interval '10 seconds' WHERE \"MaPhienTruyCap\"=:id").param("id",id).update();service.nhip(id,key,true);assertThat(seconds(id)).isEqualTo(28800);assertThatThrownBy(()->service.nhip(id,"wrong-key",true)).isInstanceOf(IllegalArgumentException.class);}
    @Test void eventReplayIsAtomicAndUnsupportedSensitivePayloadIsNotStored(){String key=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();long id=service.tao(key,null);service.suKien(id,key,"XEM_TRANG","CHI_TIET",event,1L);service.suKien(id,key,"XEM_TRANG","CHI_TIET",event,2L);assertThat(jdbc.sql("SELECT count(*) FROM \"TuongTacSanPham\" WHERE \"MaPhienTruyCap\"=:id").param("id",id).query(Long.class).single()).isEqualTo(1);assertThatThrownBy(()->service.suKien(id,key,"XEM_TRANG","password=secret",UUID.randomUUID().toString(),null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.suKien(id,key,null,null,UUID.randomUUID().toString(),null)).isInstanceOf(IllegalArgumentException.class);assertThat(jdbc.sql("SELECT count(*) FROM \"SuKienTruyCap\" WHERE \"MaPhienTruyCap\"=:id").param("id",id).query(Long.class).single()).isEqualTo(1);}
    @Test void followingIsCountedOncePerProductAndConsentedSession(){String key=UUID.randomUUID().toString();long id=service.tao(key,null);service.theoDoi(id,key,1);service.theoDoi(id,key,1);assertThat(jdbc.sql("SELECT count(*) FROM \"TuongTacSanPham\" WHERE \"MaPhienTruyCap\"=:id AND \"LoaiTuongTac\"='THEO_DOI'").param("id",id).query(Long.class).single()).isEqualTo(1);var session=new MockHttpSession();long before=count("PhienTruyCap");controller.theoDoi(session,()->"khach@luma.local",1);assertThat(count("PhienTruyCap")).isEqualTo(before);}
    @Test void retentionDeletesOldSessionAndItsEventsButKeepsFreshData(){String key=UUID.randomUUID().toString();long old=service.tao(key,null),fresh=service.tao(UUID.randomUUID().toString(),null);service.suKien(old,key,"XEM_TRANG","CHI_TIET",UUID.randomUUID().toString(),1L);jdbc.sql("UPDATE \"PhienTruyCap\" SET \"NgayTao\"=clock_timestamp()-interval '91 days' WHERE \"MaPhienTruyCap\"=:id").param("id",old).update();service.donDep();assertThat(jdbc.sql("SELECT count(*) FROM \"PhienTruyCap\" WHERE \"MaPhienTruyCap\"=:id").param("id",old).query(Long.class).single()).isZero();assertThat(jdbc.sql("SELECT count(*) FROM \"PhienTruyCap\" WHERE \"MaPhienTruyCap\"=:id").param("id",fresh).query(Long.class).single()).isEqualTo(1);}
    @Test @SuppressWarnings("unchecked") void fullMonthIncludesZeroInteractionPublicProductsAndSeparatesNewModels(){var month=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Ho_Chi_Minh")).withDayOfMonth(1).minusMonths(1);jdbc.sql("UPDATE \"SanPham\" SET \"NgayTao\"=:date WHERE \"MaSanPham\" IN (1,2)").param("date",month.minusDays(1).atStartOfDay(java.time.ZoneId.of("Asia/Ho_Chi_Minh")).toOffsetDateTime()).update();jdbc.sql("UPDATE \"SanPham\" SET \"NgayTao\"=:date WHERE \"MaSanPham\"=3").param("date",month.plusDays(3).atStartOfDay(java.time.ZoneId.of("Asia/Ho_Chi_Minh")).toOffsetDateTime()).update();String key=UUID.randomUUID().toString();long id=service.tao(key,null);service.suKien(id,key,"XEM_TRANG","CHI_TIET",UUID.randomUUID().toString(),1L);jdbc.sql("UPDATE \"TuongTacSanPham\" SET \"NgayTao\"=:date WHERE \"MaPhienTruyCap\"=:id").param("date",month.plusDays(5).atStartOfDay(java.time.ZoneId.of("Asia/Ho_Chi_Minh")).toOffsetDateTime()).param("id",id).update();var result=reports.xem("admin@luma.local",month,java.time.YearMonth.from(month).atEndOfMonth(),"month");var rows=(List<Map<String,Object>>)result.get("tuongTac");assertThat(rows).anySatisfy(r->{assertThat(((Number)r.get("MaSanPham")).longValue()).isEqualTo(2);assertThat(((Number)r.get("xem")).longValue()).isZero();assertThat(r.get("co_du_lieu")).isEqualTo(true);assertThat(r.get("moi")).isEqualTo(false);});assertThat(rows).anySatisfy(r->{assertThat(((Number)r.get("MaSanPham")).longValue()).isEqualTo(3);assertThat(r.get("moi")).isEqualTo(true);});}
}
